import Link from "next/link";
import { notFound } from "next/navigation";
import { AlertCircle, CheckCircle2, Clock3, ExternalLink, Mail, MapPin, Phone, Plus, Settings2, ShieldCheck, UserRound, Wrench } from "lucide-react";
import { Prisma } from "@prisma/client";
import { requireUser, hasAllPropertyAccess } from "@/lib/auth";
import { requirePropertyAccess } from "@/lib/access";
import { money, date, phone } from "@/lib/format";
import { moneyInput } from "@/lib/forms";
import { prisma } from "@/lib/db";
import { Shell } from "@/components/Shell";
import { PropertySubnav } from "@/components/PropertySubnav";
import { Flash } from "@/components/FormUi";
import { currentPeriod } from "@/lib/period";
import { overdueDebtCents, paidCents } from "@/lib/charges";
import { complianceResults, contactCategories, leaseStatuses, matchingRuleActions, paymentStatuses, propertyPermissions, taskCategories, taskPriorities, taskStatuses, unitOperationalStatuses, unitTypes } from "@/lib/labels";
import { buildingTypeOptions, constructionTypeOptions, energyRatingOptions, optionLabel, readPropertyTechnicalData } from "@/lib/property-technical";
import { UserAvatar } from "@/components/UserAvatar";
import { leaseAlertsForProperties } from "@/lib/lease-alerts";
import { appSettings } from "@/lib/settings";
import { complianceState, openTaskStatuses } from "@/lib/operations";
import { verificationCodeForAccount } from "@/lib/bank-email-verification";
import { bankVerificationCoverage } from "@/lib/bank-verification-scope";
import { currentLeaseForUnit, leaseStatusAt } from "@/lib/lease-lifecycle-core";
import { ownerSelfServiceScope } from "@/lib/owner-self-service";
import { PropertyIcon } from "@/components/PropertyIcon";
import { isPropertyLocalInvitation } from "@/lib/user-access-management";
import { formatPropertyBusinessId } from "@/lib/business-identity";

export const dynamic = "force-dynamic";

type PaymentRow = Prisma.BankTransactionGetPayload<{
  include: {
    bankAccount: true;
    allocations: true;
    suggestedLease: { include: { unit: true; tenant: true } };
  };
}>;

type MatchingRuleRow = Prisma.BankMatchingRuleGetPayload<{
  include: {
    bankAccount: true;
    targetLease: { include: { unit: true; tenant: true } };
  };
}>;

export default async function PropertyPage({ params, searchParams }: { params: Promise<{ id: string; section: string }>; searchParams: Promise<{ ok?: string; error?: string; invite?: string }> }) {
  const { id, section } = await params;
  const query = await searchParams;
  const user = await requireUser();
  const p = await requirePropertyAccess(user, id);
  if (!p) notFound();
  const membership = p.memberships.find((row) => row.userId === user.id);
  const propertyWide = hasAllPropertyAccess(user) || Boolean(membership);
  const ownerBankView = user.role === "OWNER_VIEWER" && section === "banka";
  if(!propertyWide&&!["prehled","jednotky","najemnici","smlouvy","platby","dluznici","banka"].includes(section))notFound();
  if(section === "banka" && !propertyWide && !ownerBankView) notFound();
  const visibleUnitIds = p.units.map(unit=>unit.id);
  const canManage = hasAllPropertyAccess(user) || membership?.permission === "EDIT" || membership?.permission === "ADMIN";
  const canAdmin = hasAllPropertyAccess(user) || membership?.permission === "ADMIN";
  const period = currentPeriod();
  const leases = p.units.flatMap((unit) => unit.leases.map((lease) => ({ ...lease, unit })));
  const currentCharges = leases.flatMap((lease) => lease.charges.filter((charge) => charge.period === period && charge.active).map((charge) => ({ lease, charge, paid: paidCents(charge) })));
  const allCharges = leases.flatMap((lease) => lease.charges.map((charge) => ({ lease, charge, paid: paidCents(charge) }))).sort((a, b) => b.charge.dueDate.getTime() - a.charge.dueDate.getTime());
  const expected = currentCharges.reduce((sum, row) => sum + row.charge.amountCents, 0);
  const paid = currentCharges.reduce((sum, row) => sum + row.paid, 0);
  const txs = await prisma.bankTransaction.findMany({
    where: { bankAccount: { propertyId: id }, amountCents: { gt: 0 }, ...(propertyWide?{}:{OR:[{suggestedLease:{unitId:{in:visibleUnitIds}}},{allocations:{some:{charge:{lease:{unitId:{in:visibleUnitIds}}}}}}]}) },
    orderBy: { bookedAt: "desc" },
    include: { bankAccount: true, allocations: true, suggestedLease: { include: { unit: true, tenant: true } } },
  });
  const debts = allCharges.filter((row) => overdueDebtCents(row.charge) > 0);
  const overdueDebt = debts.reduce((sum, row) => sum + overdueDebtCents(row.charge), 0);
  type TenantGroup={tenant:(typeof leases)[number]["tenant"];leases:typeof leases};const tenantGroups=new Map<string,TenantGroup>();for(const lease of leases){if(!tenantGroups.has(lease.tenant.id))tenantGroups.set(lease.tenant.id,{tenant:lease.tenant,leases:leases.filter(row=>row.tenant.id===lease.tenant.id)});}const uniqueTenants=Array.from(tenantGroups.values());
  const propertyOwners = p.ownerships.length ? p.ownerships : [{ id: "legacy", ownerId: p.ownerId, owner: p.owner, shareBasisPoints: 10000, note: null }];
  const propertyOwnerNames = propertyOwners.map((row) => row.owner.name).join(", ");
  const technical = readPropertyTechnicalData(p.technicalData);
  const propertyContractAlerts = leaseAlertsForProperties([{ id: p.id, name: p.name, units: p.units }]);

  const propertyPaymentLinks = p.paymentAccounts;
  const propertyPaymentAccounts = propertyPaymentLinks.map((link) => ({ ...link.ownerBankAccount, link: { ...link, id: link.ownerBankAccountId, notificationVerifiedAt: link.ownerBankAccount.notificationVerifiedAt } }));
  const bankCoverage = bankVerificationCoverage(p.units, propertyPaymentLinks);
  const allPaymentLinksVerified = bankCoverage.allVerified;
  const bankEmailPropertyLabel = bankCoverage.totalUnits === 0
    ? "Bez jednotek"
    : bankCoverage.allVerified
      ? `Bankovní účty ${bankCoverage.verifiedUnits}/${bankCoverage.totalUnits} jednotek ověřeny`
      : bankCoverage.verifiedUnits > 0
        ? `Bankovní účty ${bankCoverage.verifiedUnits}/${bankCoverage.totalUnits} jednotek ověřeny`
        : bankCoverage.configuredUnits > 0
          ? `Bankovní účty 0/${bankCoverage.totalUnits} jednotek ověřeny`
          : "Chybí účet u jednotek";
  const allowedPaymentOwnerIds = [...new Set([p.ownerId, ...p.ownerships.map((row)=>row.ownerId), ...p.units.flatMap((unit)=>unit.ownerships.map((row)=>row.ownerId))])];

  const [propertyTasks, contacts, complianceItems, activity] = await Promise.all([
    propertyWide ? prisma.task.findMany({ where: { propertyId: id }, include: { unit: true, tenant: true, assignee: true, _count: { select: { entries: true } } }, orderBy: [{ status: "asc" }, { dueAt: "asc" }, { updatedAt: "desc" }], take: 50 }) : Promise.resolve([]),
    section === "prehled" || propertyWide ? prisma.propertyContact.findMany({ where: { propertyId: id, active: true }, orderBy: [{ emergency: "desc" }, { sortOrder: "asc" }, { name: "asc" }] }) : Promise.resolve([]),
    propertyWide ? prisma.complianceItem.findMany({ where: { propertyId: id, active: true }, include: { assignedContact: true, records: { orderBy: { performedAt: "desc" }, take: 3 } }, orderBy: { nextDueAt: "asc" } }) : Promise.resolve([]),
    propertyWide ? prisma.auditLog.findMany({ where: { propertyId: id }, include: { user: true }, orderBy: { createdAt: "desc" }, take: 40 }) : Promise.resolve([]),
  ]);
  const openTasks = propertyTasks.filter((task) => openTaskStatuses.includes(task.status));
  const dueCompliance = complianceItems.filter((item) => { const state = complianceState(item); return state.key === "overdue" || state.key === "today" || state.key === "soon" || state.key === "upcoming"; });
  const expiryAlerts = propertyContractAlerts.filter((row) => row.kind === "EXPIRY");
  const anniversaryAlerts = propertyContractAlerts.filter((row) => row.kind === "ANNIVERSARY");
  const unmatchedPropertyPayments = txs.filter((transaction) => transaction.status === "UNMATCHED" || transaction.status === "SUGGESTED");
  const attentionItems: { title: string; detail: string; href: string; tone: "bad" | "warn" | "info" }[] = [];
  if (overdueDebt > 0) attentionItems.push({ title: `Dluh po splatnosti ${money(overdueDebt)}`, detail: `${debts.length} předpisů vyžaduje kontrolu`, href: `/nemovitosti/${id}/dluznici`, tone: "bad" });
  if (unmatchedPropertyPayments.length) attentionItems.push({ title: `${unmatchedPropertyPayments.length} plateb čeká na spárování`, detail: "Zkontrolujte návrhy a nespárované transakce", href: `/nemovitosti/${id}/platby#ke-sparovani`, tone: "warn" });
  for (const task of openTasks.slice(0, 3)) attentionItems.push({ title: task.title, detail: `${taskCategories[task.category]} · ${task.assignee?.name || "bez odpovědného"}`, href: `/ukoly/${task.id}`, tone: task.priority === "URGENT" ? "bad" : "warn" });
  for (const item of dueCompliance.slice(0, 2)) attentionItems.push({ title: item.name, detail: `Revize / kontrola · ${date(item.nextDueAt)} · ${complianceState(item).label}`, href: `/nemovitosti/${id}/provoz#revize`, tone: complianceState(item).key === "overdue" ? "bad" : "warn" });
  for (const alert of propertyContractAlerts.slice(0, 2)) attentionItems.push({ title: `${alert.kind === "EXPIRY" ? "Expirace" : "Výročí"} smlouvy · ${alert.lease.unit.label}`, detail: `${alert.lease.tenant.name} · ${date(alert.date)}`, href: `/smlouvy/${alert.lease.id}`, tone: "info" });

  let owners = [] as Awaited<ReturnType<typeof prisma.owner.findMany>>;
  let rules: MatchingRuleRow[] = [];
  const bankSettings = section === "banka" ? await appSettings() : null;
  const ownerScope = ownerBankView ? await ownerSelfServiceScope(user, id) : null;
  const visiblePaymentAccounts = ownerBankView ? propertyPaymentAccounts.filter((account)=>account.ownerId===ownerScope?.id) : propertyPaymentAccounts;
  const accountUnitUses = section === "banka" ? await prisma.unitOwnership.findMany({ where: { ownerBankAccountId: { in: visiblePaymentAccounts.map((account)=>account.id) } }, include: { unit: { include: { property: { select: { id: true, name: true } } } } }, orderBy: [{ unit: { property: { name: "asc" } } }, { unit: { label: "asc" } }] }) : [];
  const availablePaymentAccounts = section === "banka" && !ownerBankView ? await prisma.ownerBankAccount.findMany({ where: { active: true, ownerId: { in: allowedPaymentOwnerIds } }, include: { owner: true }, orderBy: [{ owner: { name: "asc" } }, { label: "asc" }] }) : [];
  if (section === "vlastnici") owners = await prisma.owner.findMany({ where: { active: true }, orderBy: { name: "asc" } });
  if (section === "banka" && !ownerBankView) rules = await prisma.bankMatchingRule.findMany({
    where: { propertyId: id },
    orderBy: [{ priority: "asc" }, { createdAt: "asc" }],
    include: { bankAccount: true, targetLease: { include: { unit: true, tenant: true } } },
  });
  const propertyManagers = section === "provoz" ? await prisma.user.findMany({ where: { active: true, OR: [{ allProperties: true }, { role: { in: ["SUPER_ADMIN", "MANAGER"] } }, { memberships: { some: { propertyId: id, permission: { in: ["EDIT", "ADMIN"] } } } }] }, orderBy: { name: "asc" } }) : [];

  return <Shell user={user} taskPropertyId={id}><div className="page">
    <div className="breadcrumb"><Link href="/portfolio">Portfolio</Link><span>›</span><span>{p.name}</span></div>
    <div className="property-header" data-testid="property-header">
      <div className="property-header-identity" data-testid="property-header-identity"><div className="property-icon-frame property-icon-frame-lg"><PropertyIcon technicalData={p.technicalData} unitCount={p.units.length} size={26}/></div><small>ID nemovitosti: {formatPropertyBusinessId(p.propertyCode)}</small></div>
      <div className="property-header-summary" data-testid="property-header-summary"><h1>{p.name}</h1><a className="property-map-link" href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${p.address}, ${p.postalCode ? `${p.postalCode} ` : ""}${p.city}`)}`} target="_blank" rel="noreferrer"><MapPin size={12}/>{p.address}, {p.postalCode ? `${p.postalCode} ` : ""}{p.city}<ExternalLink size={11}/></a><div className="property-meta"><span className="meta-pill">{propertyOwnerNames}</span><span className="meta-pill">{p.units.length} jednotek</span><span className={`meta-pill ${allPaymentLinksVerified?"verified-pill":""}`}>{bankEmailPropertyLabel}</span></div></div>
      <div className="property-header-side">{canManage&&<div className="property-header-actions">{p.googleDriveFolderId&&<a className="secondary" target="_blank" rel="noreferrer" href={`https://drive.google.com/drive/folders/${encodeURIComponent(p.googleDriveFolderId)}`}><ExternalLink size={14}/> Otevřít složku na Google Drive</a>}<Link className="secondary" href={`/nemovitosti/${id}/najemnici/novy`}><Plus size={15}/> Nový nájemník</Link><Link className="primary" href={`/nemovitosti/${id}/smlouvy/nova`}><Plus size={15}/> Nová smlouva</Link></div>}<Link className="property-header-right property-header-report" href={`/reporty/saldo?propertyId=${id}`}><span>Dluh po splatnosti</span><strong className={overdueDebt ? "negative" : "positive"}>{money(overdueDebt)}</strong></Link></div>
    </div>
    <PropertySubnav propertyId={id} active={section} unitLimited={!propertyWide}/><Flash ok={query.ok} error={query.error}/>

    {section === "prehled" && <>
      <div className="stat-grid v21-stat-grid">
        <Stat href={`/reporty?view=collections&properties=${id}`} label="Inkaso" value={expected ? `${Math.round(paid / expected * 100)} %` : "—"} note={`${money(paid)} z ${money(expected)}`} good={expected ? paid >= expected : true}/><Stat href={`/reporty/saldo?propertyId=${id}`} label="Dluh" value={money(overdueDebt)} note={`${debts.length} předpisů po splatnosti`} bad={overdueDebt > 0}/><Stat href={`/nemovitosti/${id}/platby#ke-sparovani`} label="Nespárované" value={String(unmatchedPropertyPayments.length)} note="platby k potvrzení" bad={unmatchedPropertyPayments.length>0}/><Stat href={`/smlouvy/upozorneni?propertyId=${id}`} label="Smlouvy" value={String(propertyContractAlerts.length)} note={`${expiryAlerts.length} expirace · ${anniversaryAlerts.length} výročí`}/><Stat href={`/nemovitosti/${id}/provoz#revize`} label="Revize" value={String(dueCompliance.length)} note="termín do 60 dní" bad={dueCompliance.some((item)=>complianceState(item).key==="overdue")}/><Stat href={`/ukoly?status=open&propertyId=${id}`} label="Úkoly" value={String(openTasks.length)} note="otevřených případů" bad={openTasks.some((task)=>task.priority==="URGENT")}/>
      </div>
      <div className="detail-grid v21-dashboard-grid">
        <div className="card col-8 attention-card"><div className="card-head"><div><h2>Vyžaduje pozornost</h2><p className="muted-copy">Nejdůležitější provozní a ekonomické události objektu.</p></div><Link href="/ukoly">Všechny úkoly</Link></div><div className="attention-list">{attentionItems.length?attentionItems.slice(0,8).map((item,index)=><Link className={`attention-item ${item.tone}`} href={item.href} key={`${item.href}-${index}`}><span className="attention-icon">{item.tone==="bad"?<AlertCircle size={17}/>:item.tone==="warn"?<Clock3 size={17}/>:<CheckCircle2 size={17}/>}</span><span><strong>{item.title}</strong><small>{item.detail}</small></span><b>→</b></Link>):<div className="calm-state"><CheckCircle2 size={22}/><div><strong>Nic akutního</strong><span>Objekt nemá evidovanou událost vyžadující okamžitý zásah.</span></div></div>}</div></div>
        <div className="card col-4"><div className="card-head"><h2>Stav objektu</h2></div><div className="summary-list clickable-summary"><Link href={`/nemovitosti/${id}/smlouvy`}><span>Aktivní smlouvy</span><strong>{leases.filter((lease) => leaseStatusAt(lease) === "ACTIVE").length} →</strong></Link><Link href={`/nemovitosti/${id}/jednotky`}><span>Volné jednotky</span><strong>{p.units.filter((unit)=>!currentLeaseForUnit(unit.leases)).length} →</strong></Link><Link href={`/smlouvy/upozorneni?propertyId=${id}&kind=expiry`}><span>Expirace do 3 měsíců</span><strong className={expiryAlerts.length?"negative":""}>{expiryAlerts.length} →</strong></Link><Link href={`/smlouvy/upozorneni?propertyId=${id}&kind=anniversary`}><span>Výročí do 3 měsíců</span><strong>{anniversaryAlerts.length} →</strong></Link><Link href={`/nemovitosti/${id}/provoz#revize`}><span>Revize do 60 dní</span><strong className={dueCompliance.length?"negative":""}>{dueCompliance.length} →</strong></Link><Link href={`/ukoly?status=open&propertyId=${id}`}><span>Otevřené úkoly</span><strong className={openTasks.length?"negative":""}>{openTasks.length} →</strong></Link></div>{p.manager&&<div className="building-manager-card"><span className="eyebrow">Správce budovy</span><div className="manager-contact"><UserAvatar user={p.manager}/><div><strong>{p.manager.name}</strong>{p.manager.title&&<span>{p.manager.title}</span>}{p.manager.phone&&<a href={`tel:${p.manager.phone}`}><Phone size={13}/>{phone(p.manager.phone)}</a>}<a href={`mailto:${p.manager.email}`}><Mail size={13}/>{p.manager.email}</a></div></div></div>}</div>
        <div className="card col-8"><div className="card-head"><h2>Poslední platby</h2><Link href={`/nemovitosti/${id}/platby`}>Zobrazit vše</Link></div><TablePayments propertyId={id} txs={txs.slice(0,6)}/></div>
        <div className="card col-4"><div className="card-head"><div><h2>Důležité kontakty</h2><p className="muted-copy">Kontakty důležité pro provoz objektu.</p></div>{canManage&&<Link href={`/nemovitosti/${id}/provoz#kontakty`}>Spravovat</Link>}</div><div className="contact-quick-list">{contacts.length?contacts.slice(0,4).map((contact)=><div className="contact-quick contact-preview-card" key={contact.id}><div className={`round-icon ${contact.emergency?"danger-round":""}`}>{contact.emergency?"!":<UserRound size={14}/>}</div><div><strong>{contact.name}</strong><small>{contactCategories[contact.category]}</small>{contact.company&&<span>{contact.company}</span>}{contact.phone&&<a href={`tel:${contact.phone}`}><Phone size={12}/>{phone(contact.phone)}</a>}{contact.email&&<a href={`mailto:${contact.email}`}><Mail size={12}/>{contact.email}</a>}</div></div>):<div className="table-empty">Důležité kontakty zatím nejsou vyplněny.</div>}</div>{contacts.length>4&&<Link className="contact-show-all" href={`/nemovitosti/${id}/provoz#kontakty`}>Zobrazit všechny →</Link>}</div>
      </div>
    </>}

    {section === "jednotky" && <SectionCard title="Jednotky" action={canManage ? <Link className="primary" href={`/nemovitosti/${id}/jednotky/nova`}><Plus size={15}/> Přidat jednotku</Link> : null}><ClickableTable headers={["Jednotka", "Typ", "Podlaží", "Plocha", "Vlastník", "Nájemník", "Stav", ""]} rows={p.units.map((unit) => { const active = currentLeaseForUnit(unit.leases); const unitOwnerNames = unit.ownerships.length ? unit.ownerships.map((row) => row.owner.name).join(", ") : propertyOwnerNames; const occupancy = active ? "Obsazená" : "Volná"; const operation = unit.operationalStatus !== "STANDARD" ? ` · ${unitOperationalStatuses[unit.operationalStatus]}` : ""; return { href: `/nemovitosti/${id}/jednotky/${unit.id}`, cells: [<strong key="l">{unit.label}</strong>, unitTypes[unit.type], unit.floor || "—", unit.areaM2 ? `${unit.areaM2} m²` : "—", unitOwnerNames, active ? active.tenant.name : "Volná", <span className={`status ${active ? "ok" : unit.operationalStatus === "RENOVATION" ? "warn" : ""}`} key="s">{occupancy}{operation}</span>, <span className="table-link" key="e">Detail</span>] }; })}/></SectionCard>}

    {section === "vlastnici" && <div className="detail-grid">
      <div className="card col-7"><div className="card-head"><div><h2>Hlavní vlastník / SVJ</h2><p className="muted-copy">U objektu se eviduje jeden hlavní vlastník nebo profil SVJ. Vlastníci jednotlivých bytů se nastavují přímo u jednotek.</p></div></div><div className="manager-profile"><div className="avatar">{p.owner.name.split(" ").map(part=>part[0]).slice(0,2).join("")}</div><div><Link className="entity-link" href={`/vlastnici/${p.owner.id}`}>{p.owner.name}</Link><span>{p.owner.ico ? `IČO ${p.owner.ico}` : p.owner.type === "PERSON" ? "Fyzická osoba" : "Právnická osoba / SVJ"}</span>{p.owner.phone&&<a href={`tel:${p.owner.phone}`}><Phone size={13}/>{phone(p.owner.phone)}</a>}{p.owner.email&&<a href={`mailto:${p.owner.email}`}><Mail size={13}/>{p.owner.email}</a>}<Link className="profile-action" href={`/vlastnici/${p.owner.id}`}>Zobrazit profil →</Link></div></div></div>
      <div className="card col-5"><h2>Změnit hlavního vlastníka</h2><p className="muted-copy">Změna nahradí současného vlastníka objektu. Pro SVJ vyberte jeho samostatný profil s IČO.</p>{canManage&&<form className="compact-form" action={`/api/properties/${id}/ownerships`} method="post"><label className="field"><span>Vlastník / SVJ</span><select name="ownerId" defaultValue={p.ownerId} required>{owners.map(owner=><option value={owner.id} key={owner.id}>{owner.name}{owner.ico?` · IČO ${owner.ico}`:""}</option>)}</select></label><button className="primary" type="submit">Uložit vlastníka</button></form>}</div>
      <div className="card col-12"><div className="card-head"><h2>Vlastníci jednotlivých jednotek</h2></div><GenericTable headers={["Jednotka","Vlastník","Nájemník",""]} rows={p.units.map(unit=>{const lease=currentLeaseForUnit(unit.leases);const owner=unit.ownerships[0]?.owner;return [<Link className="entity-link" key="u" href={`/nemovitosti/${id}/jednotky/${unit.id}`}>{unit.label}</Link>,owner?<Link className="entity-link" href={`/vlastnici/${owner.id}`}>{owner.name}</Link>:"Nenastaveno",lease?<Link className="entity-link" href={`/najemnici/${lease.tenant.id}`}>{lease.tenant.name}</Link>:"Volná",canManage?<Link className="table-link" key="e" href={`/nemovitosti/${id}/jednotky/${unit.id}/upravit`}>Nastavit vlastníka</Link>:""]})}/></div>
    </div>}

    {section === "najemnici" && <SectionCard title="Nájemníci" action={canManage ? <Link className="primary" href={`/nemovitosti/${id}/najemnici/novy`}><Plus size={15}/> Přidat nájemníka</Link> : null}><GenericTable headers={["Nájemník", "Jednotky", "E-mail", "Telefon", "Stav", ""]} rows={uniqueTenants.map(({ tenant, leases: tenantLeases }) => [<Link className="entity-link" key="n" href={`/najemnici/${tenant.id}`}>{tenant.name}</Link>, tenantLeases.map((lease) => <Link className="entity-link inline-entity" key={lease.id} href={`/nemovitosti/${id}/jednotky/${lease.unit.id}`}>{lease.unit.label}</Link>), tenant.email ? <a href={`mailto:${tenant.email}`}>{tenant.email}</a> : "—", tenant.phone ? <a href={`tel:${tenant.phone}`}>{phone(tenant.phone)}</a> : "—", <span className={`status ${tenantLeases.some((lease)=>leaseStatusAt(lease)==="ACTIVE") ? "ok" : tenantLeases.some((lease)=>leaseStatusAt(lease)==="FUTURE") ? "warn" : ""}`} key="s">{tenantLeases.some((lease)=>leaseStatusAt(lease)==="ACTIVE") ? "Aktuální nájem" : tenantLeases.some((lease)=>leaseStatusAt(lease)==="FUTURE") ? "Budoucí nájem" : "Bývalý nájemník"}</span>, canManage ? <Link className="table-link" key="e" href={`/nemovitosti/${id}/najemnici/${tenant.id}/upravit`}>Upravit</Link> : ""])}/></SectionCard>}

    {section === "smlouvy" && <SectionCard title="Nájemní smlouvy" action={canManage ? <Link className="primary" href={`/nemovitosti/${id}/smlouvy/nova`}><Plus size={15}/> Přidat smlouvu</Link> : null}><GenericTable headers={["Jednotka", "Nájemník", "Číslo smlouvy", "Od", "Do", "Placení", "Měsíčně", "Stav", ""]} rows={leases.map((lease) => [<Link className="entity-link" key="u" href={`/nemovitosti/${id}/jednotky/${lease.unit.id}`}>{lease.unit.label}</Link>, <Link className="entity-link" key="t" href={`/najemnici/${lease.tenant.id}`}>{lease.tenant.name}</Link>, <Link className="entity-link" key="c" href={`/smlouvy/${lease.id}`}>{lease.contractNumber || "Bez čísla"}</Link>, date(lease.startDate), lease.endDate ? date(lease.endDate) : "neurčito", lease.rentTiming === "ARREARS" ? "Zpětně" : "Dopředně", money(lease.rentCents + lease.servicesCents), leaseStatuses[leaseStatusAt(lease)], canManage ? <Link className="table-link" key="e" href={`/nemovitosti/${id}/smlouvy/${lease.id}/upravit`}>Upravit</Link> : ""])}/></SectionCard>}

    {section === "predpisy" && <SectionCard title="Předpisy podle jednotek" action={null}><div className="notice" style={{margin:"0 18px 14px"}}>Předpisy se nově vytvářejí a upravují v detailu konkrétní jednotky. Vyberte jednotku níže.</div><GenericTable headers={["Jednotka","Nájemník","Aktivní smlouva","Poslední předpis",""]} rows={p.units.map(unit=>{const lease=currentLeaseForUnit(unit.leases);const latest=lease?.charges[0];return [<Link className="entity-link" key="u" href={`/nemovitosti/${id}/jednotky/${unit.id}`}>{unit.label}</Link>,lease?<Link className="entity-link" href={`/nemovitosti/${id}/najemnici/${lease.tenant.id}/upravit`}>{lease.tenant.name}</Link>:"Volná",lease?money(lease.rentCents + lease.servicesCents):"—",latest?`${latest.period} · ${money(latest.amountCents)}`:"—",<Link className="table-link" key="d" href={`/nemovitosti/${id}/jednotky/${unit.id}`}>Otevřít jednotku</Link>]})}/></SectionCard>}

    {section === "platby" && <div className="detail-grid">
      <div className="card col-12 portfolio-table-card" id="ke-sparovani"><div className="table-toolbar"><div><h2>Vyžaduje řešení</h2><p>Příchozí platby bez jednoznačného finálního zaúčtování.</p></div>{canManage ? <Link className="primary" href="/platby/nova"><Plus size={15}/> Ruční platba</Link> : null}</div><TablePayments propertyId={id} txs={txs.filter((row) => row.status === "UNMATCHED" || row.status === "SUGGESTED")} empty="Žádná platba nevyžaduje řešení"/></div>
      <div className="card col-12 portfolio-table-card"><div className="table-toolbar"><div><h2>Vyřešené platby</h2><p>Platby zaúčtované automaticky nebo ručně.</p></div></div><TablePayments propertyId={id} txs={txs.filter((row) => row.status === "MATCHED" || row.status === "PARTIAL" || row.status === "OVERPAYMENT")} empty="Zatím bez vyřešených plateb"/></div>
      {txs.some((row) => row.status === "IGNORED") && <div className="card col-12"><details><summary>Ignorované pohyby ({txs.filter((row) => row.status === "IGNORED").length})</summary><div className="portfolio-table-card" style={{marginTop:12}}><p className="muted-copy">Nerelevantní příjmy vyřazené pravidlem nebo ručně.</p><TablePayments propertyId={id} txs={txs.filter((row) => row.status === "IGNORED")} empty="Bez ignorovaných plateb"/></div></details></div>}
    </div>}

    {section === "dluznici" && <SectionCard title="Otevřené pohledávky" action={null}><GenericTable headers={["Nájemník", "Jednotka", "Období", "Splatnost", "Předpis", "Uhrazeno", "Dluh"]} rows={debts.map((row) => [row.lease.tenant.name, row.lease.unit.label, <Link className="table-link" key="p" href={`/nemovitosti/${id}/predpisy/mesicni/${row.charge.id}`}>{row.charge.period}</Link>, date(row.charge.dueDate), money(row.charge.amountCents), money(row.paid), <strong className="negative" key="d">{money(overdueDebtCents(row.charge))}</strong>])}/></SectionCard>}

    {section === "technicke-udaje" && <div className="detail-grid"><div className="card col-8"><div className="card-head"><div><h2>Technický pasport budovy</h2><p className="muted-copy">Základní údaje pro provoz, pojištění, energetiku a evidenci objektu.</p></div>{canManage&&<Link className="primary" href={`/nemovitosti/${id}/upravit#technicke-udaje`}><Settings2 size={15}/> Upravit údaje</Link>}</div><div className="technical-summary-grid"><TechnicalItem label="Typ objektu" value={optionLabel(buildingTypeOptions,technical.buildingType)}/><TechnicalItem label="Konstrukce" value={optionLabel(constructionTypeOptions,technical.constructionType)}/><TechnicalItem label="Rok výstavby" value={technical.yearBuilt}/><TechnicalItem label="Poslední rekonstrukce" value={technical.yearRenovated}/><TechnicalItem label="Podlaží" value={technical.floorsAbove!=null?`${technical.floorsAbove} NP${technical.floorsBelow?` + ${technical.floorsBelow} PP`:""}`:null}/><TechnicalItem label="Celková plocha" value={technical.totalAreaM2!=null?`${technical.totalAreaM2} m²`:null}/><TechnicalItem label="Zastavěná plocha" value={technical.builtUpAreaM2!=null?`${technical.builtUpAreaM2} m²`:null}/><TechnicalItem label="Plocha pozemku" value={technical.landAreaM2!=null?`${technical.landAreaM2} m²`:null}/><TechnicalItem label="Vytápění" value={technical.heatingType}/><TechnicalItem label="Ohřev vody" value={technical.hotWaterType}/><TechnicalItem label="PENB" value={optionLabel(energyRatingOptions,technical.energyRating)}/><TechnicalItem label="Výtahy" value={technical.elevatorCount}/><TechnicalItem label="Parkovací místa" value={technical.parkingSpaces}/><TechnicalItem label="Bezbariérovost" value={technical.barrierFree?"Ano":"Ne"}/><TechnicalItem label="Sklepy" value={technical.hasCellars?"Ano":"Ne"}/><TechnicalItem label="Balkony / lodžie" value={technical.hasBalconies?"Ano":"Ne"}/></div></div><div className="card col-4"><h2>Katastr a energie</h2><div className="summary-list"><div><span>Katastrální území</span><strong>{technical.cadastralArea||"Neuvedeno"}</strong></div><div><span>Parcela</span><strong>{technical.parcelNumber||"Neuvedeno"}</strong></div><div><span>List vlastnictví</span><strong>{technical.landRegistryNumber||"Neuvedeno"}</strong></div><div><span>Číslo budovy</span><strong>{technical.buildingNumber||"Neuvedeno"}</strong></div><div><span>EAN elektřiny</span><strong>{technical.electricityEan||"Neuvedeno"}</strong></div><div><span>EIC plynu</span><strong>{technical.gasEic||"Neuvedeno"}</strong></div></div></div><div className="card col-6"><h2>Pojištění</h2><div className="summary-list"><div><span>Pojišťovna</span><strong>{technical.insurer||"Neuvedeno"}</strong></div><div><span>Číslo smlouvy</span><strong>{technical.policyNumber||"Neuvedeno"}</strong></div><div><span>Roční pojistné</span><strong>{technical.annualInsuranceCents!=null?money(technical.annualInsuranceCents):"Neuvedeno"}</strong></div></div></div><div className="card col-6"><h2>Technická poznámka</h2><p className="technical-note">{technical.technicalNote||"Zatím nebyla doplněna žádná technická poznámka."}</p></div></div>}

    {section === "provoz" && <div className="detail-grid">
      <div className="card col-12 portfolio-table-card"><div className="table-toolbar"><div><h2>Úkoly a případy</h2><p>Provozní fronta objektu. Upomínkové případy vznikají automaticky a uchovávají celé komunikační vlákno.</p></div><div className="toolbar-actions"><Link className="secondary" href={`/ukoly?propertyId=${id}`}>Všechny úkoly</Link>{canManage&&<Link className="primary" href={`/ukoly/novy?propertyId=${id}`}><Plus size={15}/> Nový úkol</Link>}</div></div><div className="table-wrap"><table><thead><tr><th>Úkol</th><th>Typ</th><th>Odpovědný</th><th>Termín</th><th>Priorita</th><th>Stav</th><th></th></tr></thead><tbody>{propertyTasks.length?propertyTasks.slice(0,15).map((task)=><tr key={task.id}><td><strong>{task.title}</strong><span className="owner-sub">{task.unit?.label||"Celý objekt"}{task.tenant?` · ${task.tenant.name}`:""} · {task._count.entries} záznamů</span></td><td>{taskCategories[task.category]}</td><td>{task.assignee?.name||"Nepřiřazen"}</td><td>{task.dueAt?date(task.dueAt):"—"}</td><td><span className={`status ${task.priority==="URGENT"?"bad":task.priority==="HIGH"?"warn":""}`}>{taskPriorities[task.priority]}</span></td><td><span className={`status ${task.status==="DONE"?"ok":task.status==="WAITING"?"warn":""}`}>{taskStatuses[task.status]}</span></td><td><Link className="table-link" href={`/ukoly/${task.id}`}>Vlákno</Link></td></tr>):<tr><td className="table-empty" colSpan={7}>Zatím bez provozních úkolů.</td></tr>}</tbody></table></div></div>

      <div className="card col-7" id="revize"><div className="card-head"><div><h2>Revize a povinné kontroly</h2><p className="muted-copy">Termín, odpovědný technik a historie provedených kontrol.</p></div><Link href="/revize">Portfolio revizí</Link></div><div className="compliance-list">{complianceItems.length?complianceItems.map((item)=>{const state=complianceState(item);return <div className="compliance-row" key={item.id}><div className="compliance-main"><div className={`round-icon ${state.tone}`}>{state.key==="overdue"?<AlertCircle size={15}/>:<ShieldCheck size={15}/>}</div><div><strong>{item.name}</strong><small>{item.category} · další termín {date(item.nextDueAt)} · {item.assignedContact?.name||"bez technika"}</small></div></div><span className={`status ${state.tone}`}>{state.label}</span>{canManage&&<details className="compliance-complete"><summary>Provedeno</summary><form className="compact-form" action={`/api/properties/${id}/compliance/${item.id}/complete`} method="post" encType="multipart/form-data"><label className="field"><span>Datum kontroly</span><input name="performedAt" type="date" defaultValue={new Date().toISOString().slice(0,10)} required/></label><label className="field"><span>Výsledek</span><select name="result" defaultValue="OK">{Object.entries(complianceResults).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><label className="field"><span>Provedl</span><input name="performedBy" defaultValue={item.assignedContact?.name||""}/></label><label className="field"><span>Další termín (volitelně)</span><input name="nextDueAt" type="date"/></label><label className="field field-full"><span>Poznámka</span><textarea name="note" rows={2}/></label><label className="field field-full"><span>Revizní protokol</span><input name="files" type="file" multiple/></label><button className="secondary" type="submit">Uložit provedení</button></form></details>}</div>}):<div className="table-empty">Žádné revize ani povinné kontroly zatím nejsou nastaveny.</div>}</div>{canManage&&<details className="create-panel"><summary><Plus size={14}/> Přidat revizi / kontrolu</summary><form className="form-grid" action={`/api/properties/${id}/compliance`} method="post"><label className="field"><span>Název</span><input name="name" required placeholder="Revize elektro společných prostor"/></label><label className="field"><span>Kategorie</span><input name="category" required placeholder="Elektro / PO / výtah / kotelna…"/></label><label className="field"><span>Periodicita v měsících</span><input type="number" min="1" name="frequencyMonths" placeholder="12"/></label><label className="field"><span>Další termín</span><input type="date" name="nextDueAt" required/></label><label className="field"><span>Technik / dodavatel</span><select name="assignedContactId"><option value="">Nepřiřazen</option>{contacts.map((contact)=><option key={contact.id} value={contact.id}>{contact.name}</option>)}</select></label><label className="field field-full"><span>Poznámka</span><textarea name="note" rows={2}/></label><div className="form-actions field-full"><button className="primary" type="submit">Přidat kontrolu</button></div></form></details>}</div>

      <div className="card col-5" id="kontakty"><div className="card-head"><div><h2>Důležité kontakty</h2><p className="muted-copy">Havarijní a servisní kontakty dostupné přímo u objektu.</p></div></div><div className="contact-list">{contacts.length?contacts.map((contact)=><div className="contact-card" key={contact.id}><div className="contact-card-top"><div><strong>{contact.name}</strong><small>{contactCategories[contact.category]}{contact.company?` · ${contact.company}`:""}</small></div>{contact.emergency&&<span className="status bad">Havarijní</span>}</div><div className="contact-links">{contact.phone&&<a href={`tel:${contact.phone}`}><Phone size={13}/>{phone(contact.phone)}</a>}{contact.email&&<a href={`mailto:${contact.email}`}><Mail size={13}/>{contact.email}</a>}</div>{contact.note&&<p>{contact.note}</p>}{canManage&&<form action={`/api/properties/${id}/contacts/${contact.id}`} method="post"><input type="hidden" name="mode" value="delete"/><button className="text-button" type="submit">Deaktivovat</button></form>}</div>):<div className="table-empty">Kontakty zatím nejsou vyplněny.</div>}</div>{canManage&&<details className="create-panel"><summary><Plus size={14}/> Přidat důležitý kontakt</summary><form className="compact-form" action={`/api/properties/${id}/contacts`} method="post"><label className="field"><span>Typ</span><select name="category" defaultValue="OTHER">{Object.entries(contactCategories).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label><label className="field"><span>Jméno</span><input name="name" required/></label><label className="field"><span>Firma</span><input name="company"/></label><label className="field"><span>Telefon</span><input name="phone"/></label><label className="field"><span>E-mail</span><input name="email" type="email"/></label><label className="checkbox-field"><input type="checkbox" name="emergency"/><span>Havarijní kontakt</span></label><label className="field"><span>Poznámka</span><textarea name="note" rows={2}/></label><button className="primary" type="submit">Přidat kontakt</button></form></details>}</div>

      <div className="card col-12" id="aktivita"><div className="card-head"><div><h2>Aktivita a provozní deník</h2><p className="muted-copy">Auditní stopa změn a ruční zápisy správce v jednom chronologickém přehledu.</p></div></div>{canManage&&<form className="logbook-composer" action={`/api/properties/${id}/logbook`} method="post"><input type="hidden" name="category" value="NOTE"/><textarea name="body" rows={3} required placeholder="Např. Kontrola střechy: zjištěno zatékání u komína, objednán klempíř."/><button className="primary" type="submit">Přidat zápis</button></form>}<div className="activity-thread">{activity.length?activity.map((entry)=>{const human=entry.action==="PROPERTY_LOG_NOTE";return <article className={`activity-entry ${human?"human-note":"system-event"}`} key={entry.id}><div className="activity-avatar">{human?<UserAvatar user={entry.user||{name:"Správce"}}/>:<Settings2 size={16}/>}</div><div className="activity-content"><div className="activity-heading"><strong>{activityLabel(entry.action)}</strong><span className={`activity-badge ${human?"note":"system"}`}>{human?"Poznámka správce":"Systémová událost"}</span></div><p>{auditText(entry.details)||`${entry.entityType}${entry.entityId?` · ${entry.entityId.slice(0,8)}`:""}`}</p><footer><span>{entry.user?.name||"FlatCloud systém"}</span><time>{entry.createdAt.toLocaleString("cs-CZ")}</time></footer></div></article>}):<div className="table-empty">Pro tento objekt zatím není evidována aktivita.</div>}</div></div>
    </div>}

    {section === "banka" && <div className="detail-grid bank-email-page">{ownerBankView ? <>
      <div className="card col-12"><div className="card-head"><div><h2>Můj bankovní účet a notifikace</h2><p className="muted-copy">Zde můžete spravovat pouze účty skutečně přiřazené k vašim dostupným jednotkám.</p></div></div>{ownerScope ? <><div className="owner-unit-list"><strong>Vaše jednotky</strong>{ownerScope.unitOwnerships.map((ownership)=><span key={ownership.id}>{ownership.unit.property.name} – {ownership.unit.label}</span>)}</div>{ownerScope.paymentAccounts.map((account)=><form id={`ucet-${account.id}`} className="owner-bank-form" action={`/api/properties/${id}/owner-bank-account`} method="post" key={account.id}><input type="hidden" name="accountId" value={account.id}/><h3>{account.label||"Bankovní účet"}</h3><div className="form-grid"><label className="field"><span>Označení</span><input name="label" defaultValue={account.label||""}/></label><label className="field"><span>Číslo účtu</span><input name="accountNumber" defaultValue={account.accountNumber||""}/></label><label className="field"><span>Kód banky</span><input name="bankCode" defaultValue={account.bankCode||""}/></label><label className="field"><span>IBAN</span><input name="iban" defaultValue={account.iban||""}/></label></div><button className="primary" type="submit">Uložit údaje účtu</button>{visiblePaymentAccounts.find((item)=>item.id===account.id)?.link && <a className="bank-status-link" href={`#overeni-${account.id}`}>{visiblePaymentAccounts.find((item)=>item.id===account.id)?.link.notificationVerifiedAt?"Ověřeno":"Čeká na ověření"} →</a>}</form>)}<form className="owner-bank-form" action={`/api/properties/${id}/owner-bank-account`} method="post"><h3>Přidat bankovní účet</h3><div className="form-grid"><label className="field"><span>Označení</span><input name="label" placeholder="Účet pro nájemné"/></label><label className="field"><span>Číslo účtu</span><input name="accountNumber"/></label><label className="field"><span>Kód banky</span><input name="bankCode"/></label><label className="field"><span>IBAN</span><input name="iban"/></label></div><fieldset className="owner-unit-picker"><legend>Přiřadit k jednotkám</legend>{ownerScope.unitOwnerships.map((ownership)=><label className="checkbox-field" key={ownership.id}><input type="checkbox" name="unitIds" value={ownership.unitId} defaultChecked={ownerScope.unitOwnerships.length===1}/><span>{ownership.unit.property.name} – {ownership.unit.label}</span></label>)}</fieldset><button className="primary" type="submit">Připojit účet k vybraným jednotkám</button></form></> : <div className="notice">Vaši identitu vlastníka nelze bezpečně propojit s dostupnou jednotkou. Bankovní účet musí připojit správce nemovitosti.</div>}</div>
      <div className="card col-12"><div className="card-head"><div><h2>Jak propojit banku přes e-mail</h2><p className="muted-copy">Notifikace se ověřuje jen pro vaše jednotky používající daný účet.</p></div></div><BankNotificationGuide mailbox={bankSettings?.inboundMailUser||"platby@flatcloud.cz"}/>{visiblePaymentAccounts.map((account)=>{const uses=accountUnitUses.filter((use)=>use.ownerBankAccountId===account.id&&use.unit.propertyId===id);if(!uses.length)return null;return <div className="verification-box" id={`overeni-${account.id}`} key={account.id}><div><small>{uses.map((use)=>`${use.unit.property.name} – ${use.unit.label}`).join(", ")}</small><strong>1,00 Kč · VS {verificationCodeForAccount(account.id)}</strong></div><span className={`status ${account.link.notificationVerifiedAt?"ok":"warn"}`}>{account.link.notificationVerifiedAt?"Funguje":"Čeká na test"}</span></div>})}</div>
    </> : <>
      <div className="card col-5"><div className="card-head"><div><h2>Účty vlastníků jednotek</h2><p className="muted-copy">Zobrazené jednotky vycházejí výhradně ze skutečného přiřazení účtu ve vlastnictví jednotky.</p></div></div><div className="stack-list">{propertyPaymentAccounts.length ? propertyPaymentAccounts.map((account)=>{const uses=accountUnitUses.filter((use)=>use.ownerBankAccountId===account.id);const verified=uses.length>0&&Boolean(account.link.notificationVerifiedAt);return <div className="payment-account-card" id={`ucet-${account.id}`} key={account.id}><div className="rule-summary"><div><strong>{account.owner.name} · {account.label||`${account.accountNumber||"Účet"}${account.bankCode?`/${account.bankCode}`:""}`}</strong><small>{account.iban||[account.accountNumber,account.bankCode].filter(Boolean).join(" / ")||"Doplňte číslo účtu"}</small></div><span className={`status ${verified?"ok":"warn"}`}>{uses.length===0?"Nepřiřazen k jednotce":verified?"Ověřeno":"Čeká na test"}</span></div><div className="account-unit-list"><span>Jednotky ({uses.length})</span>{uses.length?uses.map((use)=><strong key={use.id}>{use.unit.property.name} – {use.unit.label}</strong>):<strong>Žádná</strong>}</div><div className="summary-list mini-summary"><div><span>Poslední bankovní e-mail</span><strong>{account.link.lastNotificationAt?account.link.lastNotificationAt.toLocaleString("cs-CZ"):"Zatím žádný"}</strong></div>{verified&&<div><span>Ověřeno</span><strong>{account.link.notificationVerifiedAt?.toLocaleString("cs-CZ")}</strong></div>}</div>{canManage&&account.link.active&&<form className="mini-actions" action={`/api/properties/${id}/payment-accounts`} method="post"><input type="hidden" name="accountId" value={account.id}/><button className="text-button danger-text" type="submit" name="mode" value="remove">Odebrat z objektu</button></form>}</div>}) : <div className="empty-state"><h3>Chybí účet pro nájemné</h3><p>Nejdřív vyberte vlastníka a jeho bankovní účet přímo u konkrétní jednotky.</p><Link className="secondary" href={`/nemovitosti/${id}/jednotky`}>Otevřít jednotky</Link></div>}</div>{canManage&&p.ownershipMode==="WHOLE_OBJECT"&&<details className="create-panel"><summary><Plus size={14}/> Připojit účet k nemovitosti</summary><form className="compact-form" action={`/api/properties/${id}/payment-accounts`} method="post"><label className="field"><span>Účet vlastníka / SPV</span><select name="accountId" required><option value="">Vyberte účet</option>{availablePaymentAccounts.filter((account)=>!propertyPaymentLinks.some((link)=>link.ownerBankAccountId===account.id)).map((account)=><option key={account.id} value={account.id}>{account.owner.name} · {account.label||account.iban||`${account.accountNumber||"účet"}/${account.bankCode||""}`}</option>)}</select></label><label className="checkbox-field"><input name="primary" type="checkbox"/><span>Hlavní účet objektu</span></label><button className="secondary" type="submit">Připojit účet</button></form></details>}<div className="card-foot-note">Samotné připojení účtu k objektu neznamená, že jej používají všechny jednotky.</div></div>

      <div className="card col-7"><div className="card-head"><div><h2>Jak propojit banku přes e-mail</h2><p className="muted-copy">Ověřujeme účet vlastníka a jeho použití u konkrétních jednotek. Jedna ověřovací platba pokryje pouze jednotky v tomto objektu, které tento účet používají.</p></div><span className={`status ${bankSettings?.inboundMailEnabled?"ok":"warn"}`}>{bankSettings?.inboundMailEnabled?"Sběrný e-mail aktivní":"Nastavit v administraci"}</span></div><BankNotificationGuide mailbox={bankSettings?.inboundMailUser||"nejdřív nastavte sběrný e-mail v Administraci"} includeAssignment/>{propertyPaymentAccounts.map((account)=>{const coveredUnits=bankCoverage.unitStates.filter((unit)=>unit.ownerBankAccountId===account.id);if(!coveredUnits.length)return null;return <div className="verification-box" key={account.id}><div><small>{account.owner.name} · {coveredUnits.map((unit)=>unit.unitLabel).join(", ")}</small><strong>1,00 Kč · VS {verificationCodeForAccount(account.id)}</strong></div><span className={`status ${account.link.notificationVerifiedAt?"ok":"warn"}`}>{account.link.notificationVerifiedAt?"Funguje":"Čeká na test"}</span></div>})}{canManage&&<form action={`/api/properties/${id}/bank-email/check`} method="post"><button className="primary full-button" type="submit">Odeslal jsem testovací platbu – zkontrolovat schránku</button></form>}<p className="form-help">Poslední kontrola schránky: {bankSettings?.inboundMailLastCheckedAt?.toLocaleString("cs-CZ")||"zatím neproběhla"} · {bankSettings?.inboundMailLastSummary||"bez výsledku"}</p></div>

      <div className="card col-7"><div className="card-head"><div><h2>Stav zpracování plateb</h2><p className="muted-copy">Příchozí e-maily se převádějí na standardní platby a párují konzervativně podle účtu, VS, částky a známého plátce.</p></div></div><div className="payment-state-grid"><MiniState label="Nespárované" value={unmatchedPropertyPayments.filter((tx)=>tx.status==="UNMATCHED").length} bad/><MiniState label="Čekají na kontrolu" value={unmatchedPropertyPayments.filter((tx)=>tx.status==="SUGGESTED").length} warn/><MiniState label="Spárované" value={txs.filter((tx)=>tx.status==="MATCHED"||tx.status==="PARTIAL"||tx.status==="OVERPAYMENT").length} good/><MiniState label="Ignorované" value={txs.filter((tx)=>tx.status==="IGNORED").length}/></div><div className="notice matching-help"><strong>Jak párování funguje</strong><span>1. cílový účet určí okruh smluv → 2. VS určí nájemní smlouvu → 3. částka se použije pro plnou / částečnou úhradu nebo přeplatek. Známý účet plátce je pomocná indicie při chybném či chybějícím VS; nejednoznačné případy jdou do fronty ke kontrole.</span></div></div>
      <div className="card col-5"><div className="card-head"><div><h2>Pokročilá pravidla</h2><p className="muted-copy">Výjimky pro opakované případy. Běžné platby pravidlo nepotřebují.</p></div>{canManage&&<form action={`/api/properties/${id}/matching/reprocess`} method="post"><button className="secondary" type="submit">Znovu zpracovat</button></form>}</div>{rules.length?<div className="stack-list">{rules.map((rule)=><form className="inline-edit-card" action={`/api/properties/${id}/matching-rules/${rule.id}`} method="post" key={rule.id}><div className="rule-summary"><div><strong>{rule.name}</strong><small>{matchingRuleActions[rule.action]} · priorita {rule.priority}</small></div><span className={`status ${rule.active?"ok":""}`}>{rule.active?"Aktivní":"Vypnuto"}</span></div><div className="rule-conditions">{rule.counterpartyIban&&<span>Účet {rule.counterpartyIban}</span>}{rule.variableSymbol&&<span>VS {rule.variableSymbol}</span>}{rule.amountCents!==null&&<span>{money(rule.amountCents)}</span>}{rule.targetLease&&<span>{rule.targetLease.unit.label} · {rule.targetLease.tenant.name}</span>}</div>{canManage&&<button className="text-button danger-text" name="mode" value="delete" type="submit">Odstranit</button>}</form>)}</div>:<div className="table-empty">Žádná vlastní pravidla. Automatické párování funguje bez nich.</div>}</div>
      {canManage&&<div className="card col-12"><details className="create-panel"><summary><Plus size={14}/> Přidat pokročilé párovací pravidlo</summary><form className="form-grid compact-rule-form" action={`/api/properties/${id}/matching-rules`} method="post"><label className="field"><span>Název</span><input name="name" required placeholder="např. Ignorovat pravidelný interní převod"/></label><label className="field"><span>Akce</span><select name="action" defaultValue="IGNORE"><option value="IGNORE">Ignorovat</option><option value="MATCH_LEASE">Automaticky párovat</option><option value="SUGGEST_LEASE">Pouze navrhnout</option></select></label><label className="field"><span>Cílová smlouva</span><select name="targetLeaseId"><option value="">Bez cílové smlouvy</option>{leases.map((lease)=><option value={lease.id} key={lease.id}>{lease.unit.label} · {lease.tenant.name} · VS {lease.variableSymbol}</option>)}</select></label><label className="field"><span>Účet plátce</span><input name="counterpartyIban"/></label><label className="field"><span>Jméno obsahuje</span><input name="counterpartyNameContains"/></label><label className="field"><span>Variabilní symbol</span><input name="variableSymbol"/></label><label className="field"><span>Zpráva obsahuje</span><input name="messageContains"/></label><label className="field"><span>Částka</span><input name="amount" type="number" step="0.01"/></label><label className="field"><span>Priorita</span><input name="priority" type="number" defaultValue="100"/></label><label className="checkbox-field"><input name="active" type="checkbox" defaultChecked/><span>Aktivní</span></label><div className="form-actions field-full"><button className="primary" type="submit">Vytvořit pravidlo</button></div></form></details></div>}
    </>}</div>}

    {section === "uzivatele" && <div className="detail-grid"><div className="card col-7"><div className="card-head"><div><h2>Uživatelé nemovitosti</h2><p className="muted-copy">Přístup lze omezit jen na zobrazení, povolit editaci, nebo správu uživatelů objektu.</p></div></div><div className="stack-list">{p.memberships.length ? p.memberships.map((row) => <form className="inline-edit-card member-card" action={`/api/properties/${id}/memberships/${row.userId}`} method="post" key={row.userId}><div className="rule-summary"><div><strong>{row.user.name}</strong><small>{row.user.email}</small></div><span className={`status ${row.user.active ? "ok" : "bad"}`}>{row.user.active ? "Aktivní" : "Deaktivovaný"}</span></div><div className="member-actions"><label className="field"><span>Oprávnění</span><select name="permission" defaultValue={row.permission} disabled={!canAdmin}>{Object.entries(propertyPermissions).filter(([value]) => hasAllPropertyAccess(user) || value !== "ADMIN").map(([value, label]) => <option value={value} key={value}>{label}</option>)}</select></label>{canAdmin && <div className="mini-actions"><button className="secondary" type="submit">Uložit</button><button className="danger-button" name="mode" value="remove" type="submit">Odebrat přístup</button></div>}</div></form>) : <div className="table-empty">K nemovitosti zatím nejsou přiřazeni další uživatelé.</div>}</div></div><div className="card col-5"><h2>Přidat člena</h2><p className="muted-copy">Existujícímu aktivnímu účtu přístup přidáme rovnou; novému členovi odešleme pozvánku.</p>{canAdmin ? <form className="compact-form" action={`/api/properties/${id}/invitations`} method="post"><label className="field"><span>Jméno</span><input name="name"/></label><label className="field"><span>E-mail</span><input name="email" type="email" required/></label><label className="field"><span>Oprávnění</span><select name="permission" defaultValue="VIEW"><option value="VIEW">Pouze zobrazení</option><option value="EDIT">Zobrazení a editace</option>{hasAllPropertyAccess(user) && <option value="ADMIN">Správa objektu a uživatelů</option>}</select></label><button className="primary" type="submit">Přidat člena</button></form> : <div className="notice">Pozvánky může posílat administrátor nemovitosti.</div>}{query.invite && <div className="invite-link-box"><strong>Odkaz k ručnímu předání</strong><input readOnly value={query.invite}/></div>}</div><div className="card col-12"><h2>Čekající pozvánky</h2><div className="table-wrap"><table><thead><tr><th>E-mail</th><th>Oprávnění</th><th>Pozval</th><th>Platnost</th><th></th></tr></thead><tbody>{p.invitations.filter((invite) => invite.status === "PENDING" && isPropertyLocalInvitation(invite, id)).length ? p.invitations.filter((invite) => invite.status === "PENDING" && isPropertyLocalInvitation(invite, id)).map((invite) => <tr key={invite.id}><td>{invite.email}</td><td>{propertyPermissions[invite.permission]}</td><td>{invite.invitedBy.name}</td><td>{date(invite.expiresAt)}</td><td>{canAdmin && <div className="pending-invite-actions"><form action={`/api/invitations/${invite.id}/rotate`} method="post"><input type="hidden" name="returnTo" value={`/nemovitosti/${id}/uzivatele`}/><button className="secondary" name="mode" value="resend">Odeslat znovu</button></form><details><summary>Upravit oprávnění</summary><form className="compact-form" action={`/api/invitations/${invite.id}/rotate`} method="post"><input type="hidden" name="returnTo" value={`/nemovitosti/${id}/uzivatele`}/><input type="hidden" name="mode" value="edit"/><label className="field"><span>Oprávnění</span><select name="permission" defaultValue={invite.permission}><option value="VIEW">Pouze zobrazení</option><option value="EDIT">Zobrazení a editace</option>{hasAllPropertyAccess(user)&&<option value="ADMIN">Správa objektu a uživatelů</option>}</select></label><button className="secondary">Uložit a odeslat novou</button></form></details><form action={`/api/invitations/${invite.id}/revoke`} method="post"><input type="hidden" name="returnTo" value={`/nemovitosti/${id}/uzivatele`}/><button className="danger-button" type="submit">Zrušit</button></form></div>}</td></tr>) : <tr><td colSpan={5} className="table-empty">Bez čekajících pozvánek</td></tr>}</tbody></table></div></div></div>}
    {section === "nastaveni" && <div className="detail-grid"><div className="card col-8"><div className="card-head"><h2>Nastavení nemovitosti</h2>{canManage && <Link className="primary" href={`/nemovitosti/${id}/upravit`}><Settings2 size={15}/> Upravit</Link>}</div><div className="summary-list"><div><span>Název</span><strong>{p.name}</strong></div><div><span>Hlavní evidenční vlastník / SVJ</span><strong>{p.owner.name}</strong></div><div><span>Vlastnická struktura</span><strong>{p.ownershipMode === "WHOLE_OBJECT" ? "Jeden vlastník celého objektu" : p.ownershipMode === "SVJ" ? "SVJ – vlastníci po jednotkách" : "Různí vlastníci jednotek"}</strong></div><div><span>Hlavní komunikační vlastník</span><strong>{p.communicationOwner?.name || p.owner.name}</strong></div><div><span>Správce nemovitosti</span><strong>{p.manager?.name || "Nepřiřazen"}</strong></div><div><span>Vlastníci objektu</span><strong>{propertyOwnerNames}</strong></div><div><span>Adresa</span><strong>{p.address}, {p.city}</strong></div><div><span>Stav</span><strong>{p.active ? "Aktivní" : "Neaktivní"}</strong></div></div>{p.note && <div className="notice" style={{ marginTop: 16 }}>{p.note}</div>}</div><div className="card col-4"><h2>Bezpečnost dat</h2><p className="muted-copy">Jednotky, smlouvy, předpisy, bankovní účty i pravidla jsou vždy vázány na tento objekt. Vlastník účtu může být objekt/SVJ nebo konkrétní spoluvlastník.</p></div></div>}
  </div></Shell>;
}

function TechnicalItem({label,value}:{label:string;value:string|number|null|undefined}){return <div className="technical-item"><span>{label}</span><strong>{value===null||value===undefined||value===""?"Neuvedeno":value}</strong></div>}

function Stat({ href, label, value, note, good, bad }: { href: string; label: string; value: string; note: string; good?: boolean; bad?: boolean }) { return <Link className="card stat stat-link" href={href}><div><span>{label}</span><strong className={bad ? "negative" : good ? "positive" : ""}>{value}</strong><small className={good ? "good" : bad ? "bad" : ""}>{note}</small></div><b className="stat-arrow">→</b></Link>; }
function SectionCard({ title, action, children }: { title: string; action: React.ReactNode; children: React.ReactNode }) { return <div className="card portfolio-table-card"><div className="table-toolbar"><div><h2>{title}</h2></div>{action}</div>{children}</div>; }
function GenericTable({ headers, rows }: { headers: string[]; rows: React.ReactNode[][] }) { return <div className="table-wrap"><table><thead><tr>{headers.map((header, index) => <th key={`${header}-${index}`}>{header}</th>)}</tr></thead><tbody>{rows.length ? rows.map((row, rowIndex) => <tr key={rowIndex}>{row.map((cell, columnIndex) => <td key={columnIndex}>{cell}</td>)}</tr>) : <tr><td colSpan={headers.length} className="table-empty">Bez záznamů</td></tr>}</tbody></table></div>; }
function ClickableTable({ headers, rows }: { headers: string[]; rows: { href: string; cells: React.ReactNode[] }[] }) { return <div className="table-wrap"><table><thead><tr>{headers.map((header, index) => <th key={`${header}-${index}`}>{header}</th>)}</tr></thead><tbody>{rows.length ? rows.map((row, rowIndex) => <tr className="clickable-table-row" key={rowIndex}>{row.cells.map((cell, columnIndex) => <td key={columnIndex}><Link className="row-cell-link" href={row.href}>{cell}</Link></td>)}</tr>) : <tr><td colSpan={headers.length} className="table-empty">Bez záznamů</td></tr>}</tbody></table></div>; }
function TablePayments({ propertyId, txs, empty = "Bez transakcí" }: { propertyId: string; txs: PaymentRow[]; empty?: string }) { return <div className="table-wrap"><table><thead><tr><th>Datum</th><th>Plátce / protistrana</th><th>VS</th><th>Částka</th><th>Stav</th><th>Návrh / poznámka</th><th></th></tr></thead><tbody>{txs.length ? txs.map((transaction) => <tr key={transaction.id}><td>{date(transaction.bookedAt)}</td><td>{transaction.counterpartyName || "Plátce neuveden"}<span className="owner-sub">{transaction.counterpartyIban ? `Účet plátce: ${transaction.counterpartyIban}` : transaction.message ? `Zpráva z banky: ${transaction.message}` : "—"}</span></td><td>{transaction.variableSymbol || "—"}</td><td className="money">{money(transaction.amountCents)}</td><td><span className={`status ${transaction.status === "MATCHED" ? "ok" : transaction.status === "UNMATCHED" ? "bad" : transaction.status === "IGNORED" ? "" : "warn"}`}>{paymentStatuses[transaction.status]}</span></td><td>{transaction.suggestedLease ? `${transaction.suggestedLease.unit.label} · ${transaction.suggestedLease.tenant.name}` : transaction.matchNote || "—"}</td><td><Link className="table-link" href={`/nemovitosti/${propertyId}/platby/${transaction.id}`}>Otevřít</Link></td></tr>) : <tr><td colSpan={7} className="table-empty">{empty}</td></tr>}</tbody></table></div>; }

function Step({n,title,children}:{n:string|number;title:string;children:React.ReactNode}) { return <div className="bank-onboarding-step"><span className="step-number">{n}</span><div><strong>{title}</strong><div className="muted-copy">{children}</div></div></div>; }
function BankNotificationGuide({mailbox,includeAssignment=false}:{mailbox:string;includeAssignment?:boolean}) { const offset=includeAssignment?1:0;return <div className="owner-bank-guide">{includeAssignment&&<Step n="1" title="Přiřaďte účet ke konkrétní jednotce">Číslo účtu / IBAN vyberte u vlastnictví jednotky, na kterou chodí nájemné.</Step>}<Step n={1+offset} title="Zapněte oznámení o příchozích platbách">V bance nastavte e-mailové notifikace. Pokud banka nepovolí vlastního příjemce, nastavte je na e-mail vlastníka účtu a vytvořte obecné pravidlo pro přeposílání na <strong>{mailbox}</strong>.</Step><Step n={2+offset} title="Česká spořitelna a přeposílání">Česká spořitelna může doručovat jen na e-mail spojený s účtem. Zapněte oznámení na e-mail vlastníka a bankovní notifikace z něj přeposílejte na <strong>{mailbox}</strong>. Stejný postup použijte u jiné banky bez vlastní adresy příjemce.</Step><Step n={3+offset} title="Pošlete jedinou testovací platbu 1 Kč">Použijte uvedený testovací VS. Doručení banky i přeposílání může trvat několik minut.</Step><Step n={4+offset} title="Vyčkejte a zkontrolujte schránku">Neposílejte opakovaně další platby 1 Kč. Počkejte několik minut a potom zkontrolujte schránku.</Step></div>; }
function MiniState({label,value,tone="",good=false,bad=false,warn=false}:{label:string;value:string|number;tone?:string;good?:boolean;bad?:boolean;warn?:boolean}) { const cls=bad?"negative":good?"positive":warn?"warning":tone; return <div className="mini-state"><span>{label}</span><strong className={cls}>{value}</strong></div>; }
function activityLabel(action:string) {
  const labels: Record<string,string> = {
    PROPERTY_LOG_NOTE:"Provozní poznámka", TASK_CREATED:"Úkol vytvořen", TASK_UPDATED:"Úkol změněn", TASK_ENTRY_ADDED:"Nový záznam v úkolu",
    PROPERTY_CONTACT_CREATED:"Kontakt přidán", PROPERTY_CONTACT_UPDATED:"Kontakt změněn", COMPLIANCE_CREATED:"Revize založena", COMPLIANCE_COMPLETED:"Revize provedena",
    PAYMENT_ALLOCATED:"Platba přiřazena", PAYMENT_MANUAL_CREATED:"Ruční platba", RENT_NOTIFICATION_SENT:"Komunikace k nájmu", LEASE_UPDATED:"Smlouva upravena",
    LEASE_CREATED:"Smlouva vytvořena", TENANT_UPDATED:"Nájemník upraven", UNIT_UPDATED:"Jednotka upravena", PROPERTY_UPDATED:"Nemovitost upravena",
    INBOUND_PAYMENT_ASSIGNED:"E-mailová platba přiřazena", INBOUND_PAYMENT_IGNORED:"E-mailová platba ignorována",
    COLLECTION_TASK_CREATED:"Vytvořen úkol pro vymáhání", UNIT_OWNER_REPLACED:"Změněn vlastník jednotky",
    PROPERTY_PAYMENT_ACCOUNT_ADDED:"Přidán bankovní účet nemovitosti", PROPERTY_PAYMENT_ACCOUNT_REMOVED:"Odebrán bankovní účet nemovitosti"
  };
  return labels[action] || action.replaceAll("_"," ").toLocaleLowerCase("cs-CZ");
}
function auditText(details: unknown) {
  if (!details || typeof details !== "object" || Array.isArray(details)) return "";
  const data = details as Record<string, unknown>;
  if (typeof data.body === "string") return data.body;
  if (typeof data.title === "string") return data.title;
  if (typeof data.name === "string") return data.name;
  if (typeof data.message === "string") return data.message;
  if (typeof data.period === "string") return `Období ${data.period}`;
  return "";
}
